=== Stepper.tsx ===
import { IconCheck } from "./icons";

/**
 * Unified step indicator for the portal v2 redesign — replaces the six
 * independently-hand-rolled `Stepper` functions duplicated across
 * components/customer/{DeployWizard,HostingDeployWizard,GameDeployWizard,
 * DomainRegisterWizard,DomainTransferInWizard,MigrationWizard}.tsx.
 *
 * This component is NOT wired into any of those wizards yet (foundation-only
 * task) — that consolidation is a follow-up. It's shaped to be a drop-in
 * replacement for all six: every existing call site already passes either
 * `{ step: number; steps: string[] }` or a bare `{ step: number }` against a
 * module-level STEPS array, both of which map directly onto
 * `currentStep`/`steps` below (steps accepts plain strings, so
 * `<Stepper currentStep={step} steps={STEPS} />` is a straight swap).
 *
 * Visual spec (from scratchpad/portal-redesign-wizard.html, approved):
 * circular numbered badges that become a checkmark once passed, a connector
 * line between them that visibly fills in as steps complete, two variants
 * (gradient glow for money-path flows vs. a flat neutral look for
 * non-purchase tools like Migration/Transfer), and a mobile (<768px) collapse
 * to a compact dot-track + "Step N of M" label so a 5-6 step wizard doesn't
 * wrap into a wall of tiny badges on a phone.
 *
 * ─── Usage ───────────────────────────────────────────────────────────────
 *
 *   import { Stepper } from "@/components/portal-v2/Stepper";
 *
 *   <Stepper
 *     currentStep={step}                       // 0-indexed, matches existing wizards
 *     steps={["Plan", "Configure", "Review & pay"]}
 *     variant="default"                        // gradient glow — deploy/domain/hosting wizards
 *   />
 *
 *   // Non-purchase flow (e.g. Migration Center, Domain Transfer):
 *   <Stepper currentStep={step} steps={STEPS} variant="muted" />
 *
 *   // Steps can carry an optional description for a future richer layout —
 *   // plain strings work exactly as today's wizards already pass them:
 *   <Stepper currentStep={1} steps={[{ label: "Plan" }, "Review & pay"]} />
 */

export type StepperStep = string | { label: string; description?: string };

export interface StepperProps {
  /** 0-indexed index of the step currently on screen. */
  currentStep: number;
  /** Step labels, in order. Plain strings or `{ label, description? }`. */
  steps: StepperStep[];
  /**
   * "default" = brand gradient + glow on the current/active badge (money-path
   * flows: deploy, hosting, domain register). "muted" = flat neutral badges,
   * no gradient sweep or glow (non-purchase tools: migration, transfer-in) —
   * these still need to orient the user, just without borrowing the
   * "you're buying something" visual weight of a checkout flow.
   */
  variant?: "default" | "muted";
  className?: string;
}

function label(step: StepperStep): string {
  return typeof step === "string" ? step : step.label;
}

export function Stepper({ currentStep, steps, variant = "default", className = "" }: StepperProps) {
  const isMuted = variant === "muted";

  return (
    <div className={className}>
      {/* Desktop / tablet: full badge-and-connector row. Hidden below 768px. */}
      <ol className="hidden md:flex md:flex-wrap md:items-center md:gap-1.5" aria-label="Progress">
        {steps.map((step, i) => {
          const isDone = i < currentStep;
          const isCurrent = i === currentStep;
          return (
            <li key={label(step) + i} className="flex items-center gap-2.5">
              <div className="flex items-center gap-2.5">
                <span
                  aria-current={isCurrent ? "step" : undefined}
                  className={[
                    "flex h-7 w-7 shrink-0 items-center justify-center rounded-full border text-[11.5px] font-pv-display font-bold transition-colors duration-200",
                    isDone
                      ? isMuted
                        ? "border-white/20 bg-white/[0.06] text-pv-text"
                        : "border-pv-good/40 bg-pv-good/15 text-pv-good"
                      : isCurrent
                        ? isMuted
                          ? "border-white/40 bg-white/[0.1] text-pv-text"
                          : "border-pv-brand-light bg-pv-brand/20 text-pv-brand-light shadow-[0_0_0_4px_rgb(111_71_245_/_0.12)]"
                        : "border-white/10 text-pv-text-faint",
                  ].join(" ")}
                >
                  {isDone ? <IconCheck width={13} height={13} strokeWidth={2.4} /> : i + 1}
                </span>
                <span
                  className={
                    "text-[13px] font-medium " + (isCurrent || isDone ? "text-pv-text" : "text-pv-text-faint")
                  }
                >
                  {label(step)}
                </span>
              </div>

              {i < steps.length - 1 && (
                <span className="relative h-px w-8 overflow-hidden rounded-full bg-white/10">
                  <span
                    className={[
                      "absolute inset-y-0 left-0 rounded-full transition-[width] duration-500 ease-out",
                      isMuted ? "bg-white/40" : "bg-gradient-to-r from-pv-brand-light to-pv-cyan",
                    ].join(" ")}
                    style={{ width: isDone ? "100%" : "0%" }}
                  />
                </span>
              )}
            </li>
          );
        })}
      </ol>

      {/* Mobile: compact dot-track + "Step N of M" + current label. */}
      <div className="flex items-center gap-3 md:hidden">
        <div className="flex items-center gap-1.5" aria-hidden="true">
          {steps.map((step, i) => {
            const isDone = i < currentStep;
            const isCurrent = i === currentStep;
            return (
              <span
                key={label(step) + i}
                className={[
                  "rounded-full transition-all duration-200",
                  isCurrent
                    ? isMuted
                      ? "h-2 w-2 bg-white"
                      : "h-2 w-2 bg-pv-brand-light shadow-[0_0_6px_rgb(164_139_255_/_0.7)]"
                    : isDone
                      ? isMuted
                        ? "h-1.5 w-1.5 bg-white/50"
                        : "h-1.5 w-1.5 bg-pv-good/70"
                      : "h-1.5 w-1.5 bg-white/15",
                ].join(" ")}
              />
            );
          })}
        </div>
        <div className="min-w-0">
          <p className="text-[11px] font-medium uppercase tracking-wide text-pv-text-faint">
            Step {currentStep + 1} of {steps.length}
          </p>
          <p className="truncate font-pv-display text-[13px] font-semibold text-pv-text">
            {label(steps[currentStep] ?? steps[steps.length - 1])}
          </p>
        </div>
      </div>
    </div>
  );
}

